import React, { useRef } from "react";
import Banner from "./Banner";
import '../styles/main.css';

export default function Admissions() {
  const formRef = useRef(null);
  const onlineRef = useRef(null);
  const feeRef = useRef(null);

  const scrollToSection = (ref) => {
    ref.current.scrollIntoView({ behavior: "smooth" });
  };

  return (
    <>
      <Banner /> 
      <div className="admissions-page">
        <div className="left-column">
          <h2>Admissions</h2>
          <div className="info-box">
            <p onClick={() => scrollToSection(formRef)}>Application Form</p>
            <p onClick={() => scrollToSection(onlineRef)}>Apply Online</p>
            <p onClick={() => scrollToSection(feeRef)}>Fee Structure</p>
          </div>
        </div>

        <div className="right-column">
          <div ref={formRef}>
            <h2>Application Form</h2>
            <p>Instructions and details about application form...</p>
          </div>

          <div ref={onlineRef} style={{ marginTop: "50px" }}>
            <h2>Apply Online</h2>
            <p>Parent can fill online admission form via the button below</p>
            <button onClick={() => window.open("/admission-form", "_blank")}>Apply Now</button>
          </div>

          <div ref={feeRef} style={{ marginTop: "50px" }}>
            <h2>Fee Structure</h2>
            <table className="fee-table">
              <thead>
                <tr>
                  <th>Particular</th>
                  <th>Details</th>
                  <th>Classes</th>
                </tr>
              </thead>
              <tbody>
                <tr><td>Registration Fees</td><td>Charged at Admission</td><td>₹1000</td></tr>
                <tr><td>Admission Fees</td><td>Charged at Admission/Re-admission</td><td>₹10000</td></tr>
                <tr><td>Composite Monthly Fees</td><td>Before 15th of every month</td><td>₹1970–₹3700</td></tr>
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </>
  );
}
